{"command": "cd /workspace && python3 - <<'PY'
import json

# Correct implementation from packet
class Order:
    def __init__(self, total_cents):
        if type(total_cents) is not int or total_cents <= 0:
            raise ValueError("total must be a positive integer")
        self.total_cents = total_cents
        self.refunded_cents = 0
        self.state = "pending"

    def capture(self):
        if self.state != "pending":
            raise ValueError("capture requires pending order")
        self.state = "paid"

    def cancel(self):
        if self.state != "pending":
            raise ValueError("cancel requires pending order")
        self.state = "cancelled"

    def refund(self, amount):
        if self.state not in ("paid", "partially_refunded"):
            raise ValueError("refund requires captured payment")
        if type(amount) is not int or amount <= 0:
            raise ValueError("refund must be a positive integer")
        if amount > self.total_cents - self.refunded_cents:
            raise ValueError("refund exceeds remaining balance")
        self.refunded_cents += amount
        self.state = "refunded" if self.refunded_cents == self.total_cents else "partially_refunded"

    def summary(self):
        return {"state": self.state, "total_cents": self.total_cents,
                "refunded_cents": self.refunded_cents,
                "remaining_cents": self.total_cents - self.refunded_cents}

scenario = {
    "total_cents": 100,
    "actions": [{"op": "refund", "amount": 1}],
    "expected": {"error": "ValueError", "at_step": 0}
}

# Validate shape constraints
assert type(scenario["total_cents"]) is int and 1 <= scenario["total_cents"] <= 1000000000
assert isinstance(scenario["actions"], list) and 1 <= len(scenario["actions"]) <= 12
for a in scenario["actions"]:
    assert isinstance(a, dict) and a.get("op") in {"capture","cancel","refund"}
    if a["op"] == "refund":
        amt = a["amount"]
        assert (type(amt) is int or type(amt) is bool) and abs(amt) <= 1000000000

# Execute scenario semantics: start Order(total_cents); stop at first ValueError
def run(impl, scenario):
    order = impl(scenario["total_cents"])
    for i, action in enumerate(scenario["actions"]):
        op = action["op"]
        try:
            if op == "capture":
                order.capture()
            elif op == "cancel":
                order.cancel()
            elif op == "refund":
                order.refund(action["amount"])
            else:
                raise AssertionError(op)
        except ValueError as e:
            return {"error": "ValueError", "at_step": i}
    return order.summary()

actual = run(Order, scenario)
print("actual:", actual)
assert actual == scenario["expected"], (actual, scenario["expected"])
print("scenario passes correct implementation")

# Sanity: a faulty impl that allows any refund before capture should be exposed
class FaultyOrder(Order):
    def refund(self, amount):
        if type(amount) is not int or amount <= 0:
            raise ValueError("refund must be a positive integer")
        if amount > self.total_cents - self.refunded_cents:
            raise ValueError("refund exceeds remaining balance")
        self.refunded_cents += amount
        self.state = "refunded" if self.refunded_cents == self.total_cents else "partially_refunded"

faulty_actual = run(FaultyOrder, scenario)
print("faulty actual:", faulty_actual)
assert faulty_actual != scenario["expected"]
print("scenario distinguishes state-guard fault")
PY"}

